package org.apache.commons.math3.distribution;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.apache.commons.math3.exception.MathArithmeticException;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.apache.commons.math3.util.MathArrays;
import org.apache.commons.math3.util.Pair;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertThrows;

/**
 * Unit tests for DiscreteDistribution.sample(int)
 */
public class DiscreteDistribution_sample_TriageGen0Test {

    private List<Pair<String, Double>> sampleData;
    private DiscreteDistribution<String> distribution;

    @Before
    public void setUp() {
        sampleData = Arrays.asList(
            new Pair<>("A", 0.5),
            new Pair<>("B", 0.5)
        );
        distribution = new DiscreteDistribution<>(sampleData);
    }

    @Test
    public void testSample_Success() {
        int sampleSize = 5;
        String[] result = distribution.sample(sampleSize);

        assertNotNull(result);
        assertEquals(sampleSize, result.length);
        for (String s : result) {
            // Since it's a discrete distribution of A and B, 
            // we check if elements are within the expected set
            org.junit.Assert.assertTrue(s.equals("A") || s.equals("B"));
        }
    }

    @Test
    public void testSample_SingleElement() {
        int sampleSize = 1;
        String[] result = distribution.sample(sampleSize);

        assertNotNull(result);
        assertEquals(1, result.length);
    }

    @Test
    public void testSample_ThrowsNotStrictlyPositiveException_Zero() {
        assertThrows(NotStrictlyPositiveException.class, () -> {
            distribution.sample(0);
        });
    }

    @Test
    public void testSample_ThrowsNotStrictlyPositiveException_Negative() {
        assertThrows(NotStrictlyPositiveException.class, () -> {
            distribution.sample(-1);
        });
    }

    @Test
    public void testSample_WithIntegerDistribution() {
        // Testing with Integer type to ensure generic T works correctly for different types
        List<Pair<Integer, Double>> intData = Arrays.asList(
            new Pair<>(1, 1.0)
        );
        DiscreteDistribution<Integer> intDist = new DiscreteDistribution<>(intData);

        int sampleSize = 3;
        Integer[] result = intDist.sample(sampleSize);

        assertEquals(3, result.length);
        assertEquals(Integer.valueOf(1), result[0]);
        assertEquals(Integer.valueOf(1), result[1]);
        assertEquals(Integer.valueOf(1), result[2]);
    }
}
